# ------------------------------------------------------------------ #
# 1) lib/checkin.ts - notu guncelleyen RPC sarmalayicisi
# ------------------------------------------------------------------ #
yol = "lib/checkin.ts"
k = open(yol, encoding="utf-8").read()
isaret = "export type AktifCheckIn = CheckIn & { mekanAdi: string }"
assert k.count(isaret) == 1
yeni = '''/**
 * Paylasimin notunu degistirir; bos metin notu SILER.
 *
 * Neden RPC: `check_inler` uzerinde dogrudan update `authenticated`
 * rolunden geri alinmis durumda (mekan_id yazilabilseydi kisi kendi
 * satirini baska bir mekana tasiyabilirdi). Sunucu yalnizca notu
 * aciyor; mekan ve zaman degismiyor.
 *
 * Migrasyon: 20260902170000.
 */
export async function checkInNotunuGuncelle(checkInId: string, not: string): Promise<void> {
  const { error } = await supabase.rpc('check_in_notunu_guncelle', {
    p_check_in_id: checkInId,
    p_not: not,
  })
  if (error) throw new Error(hataMetni(error))
}

'''
k = k.replace(isaret, yeni + isaret)
open(yol, "w", encoding="utf-8", newline="\n").write(k)

# ------------------------------------------------------------------ #
# 2) OnayPenceresi - eylem dugmesine testID
# ------------------------------------------------------------------ #
yol = "src/tasarim/OnayPenceresi.tsx"
k = open(yol, encoding="utf-8").read()
esk = """          <Pressable
            style={stiller.dugme}
            onPress={onOnay}
            accessibilityRole="button"
          >"""
assert k.count(esk) == 1
k = k.replace(
    esk,
    """          <Pressable
            style={stiller.dugme}
            testID="onay-eylemi"
            onPress={onOnay}
            accessibilityRole="button"
          >""",
)
open(yol, "w", encoding="utf-8", newline="\n").write(k)

# ------------------------------------------------------------------ #
# 3) CheckInKarti - uc nokta menusu, duzenleme, eylem satiri yukari
# ------------------------------------------------------------------ #
yol = "src/tasarim/CheckInKarti.tsx"
k = open(yol, encoding="utf-8").read()

# 3a) import'lar
k = k.replace(
    "import { View, Text, Image, Pressable, StyleSheet } from 'react-native'",
    "import { useState } from 'react'\n"
    "import { View, Text, Image, Pressable, StyleSheet } from 'react-native'",
)
k = k.replace(
    "import { OnayPenceresi } from './OnayPenceresi'",
    "import { OnayPenceresi } from './OnayPenceresi'\n"
    "import { PaylasimMenusu, UcNoktaIkonu } from './PaylasimMenusu'\n"
