)
# Svg artik kartta kullanilmiyor (cop ikonu menuye tasindi).
k = k.replace("import Svg, { Path } from 'react-native-svg'\n", "")

# 3b) yerel cop ikonu kaldiriliyor
esk_ikon = """/** Silme dugmesinin ikonu. */
function CopIkonu() {
  return (
    <Svg width={18} height={18} viewBox="0 0 24 24">
      <Path
        d="M5 7h14M10 7V5.5h4V7M6.5 7l.8 12h9.4l.8-12"
