"""Expo web paketi icin kucuk SPA sunucusu.

Bilinmeyen yollar index.html'e duesuyor; yoksa expo-router yonlendirmeyi
istemcide yaptigi icin /profil gibi bir adres dogrudan acilinca 404
geliyor.

Kullanim: python spa-sunucu.py <dist yolu> <port>
"""
import os
import sys
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer

KOK = sys.argv[1]
PORT = int(sys.argv[2]) if len(sys.argv) > 2 else 8080


class Isleyici(SimpleHTTPRequestHandler):
    def __init__(self, *a, **kw):
        super().__init__(*a, directory=KOK, **kw)

    def do_GET(self):
        yol = self.translate_path(self.path)
        if not os.path.exists(yol) or os.path.isdir(yol):
            if "." not in os.path.basename(self.path):
                self.path = "/index.html"
        return super().do_GET()

    def log_message(self, *a):
        pass


ThreadingHTTPServer(("127.0.0.1", PORT), Isleyici).serve_forever()

