  await alanlar[0].type('test0@slooin.test', { delay: 10 })
  await alanlar[1].type('[SIR-GIZLENDI]', { delay: 10 })
  await sayfa.evaluate(() => {
    const hedef = [...document.querySelectorAll('div,span')].find(
      (e) => e.textContent?.trim() === 'Giriş yap' && e.children.length === 0
    )
    hedef?.closest('[role="button"]')?.click() ?? hedef?.click()
  })
  await new Promise((c) => setTimeout(c, 5000))

  await sayfa.goto(`${TABAN}/`, { waitUntil: 'networkidle0', timeout: 60000 })
  await sayfa.evaluate(() => document.fonts.ready)
