    d.dispatchEvent(new MouseEvent('click', { bubbles: true }))
    return true
  })
  console.log('menu dugmesi bulundu:', acildi)
  await new Promise((c) => setTimeout(c, 900))
  await sayfa.screenshot({ path: '../tasarim/yeni-menu.png' })

  // Duzenle
  await sayfa.evaluate(() => {
    const d = document.querySelector('[data-testid="menu-duzenle"]')
